function* counter() {
  console.log('시작!');
  yield 1; // 실행 일시 정지 (값 1 반환)
  console.log('재개!');
  yield 2; // 실행 일시 정지 (값 2 반환)
  console.log('끝!');
}

// 함수가 바로 실행되지 않고, Iterator(제어 객체)를 반환함
const gen = counter();

console.log(gen.next()); // { value: 1, done: false }
console.log(gen.next()); // { value: 2, done: false }
console.log(gen.next()); // { value: undefined, done: true }
